// Precompile only trusted, bundled JavaScript with the pinned QuickJS engine.
// Generated bytecode is part of the SO, not an external or persistent cache.
use rquickjs::{module::WriteOptions, qjs, Context, Ctx, Function, Module, Object, Runtime, Value};
use std::{env, ffi::CString, fs, path::PathBuf};

#[path = "src/browser_url.rs"]
mod browser_url;

fn compile_global(ctx: &Ctx<'_>, source: &[u8]) -> Vec<u8> {
    let input = CString::new(source).expect("fixed JS source must not contain NUL");
    // SAFETY: The input and filename remain valid during compile-only JS_Eval.
    let raw = unsafe {
        qjs::JS_Eval(
            ctx.as_raw().as_ptr(),
            input.as_ptr(),
            source.len() as _,
            c"eval_script".as_ptr(),
            (qjs::JS_EVAL_TYPE_GLOBAL | qjs::JS_EVAL_FLAG_COMPILE_ONLY) as _,
        )
    };
    if unsafe { qjs::JS_IsException(raw) } {
        panic!("compile fixed JS bootstrap: {:?}", ctx.catch());
    }
    // SAFETY: JS_Eval returned an owned, unevaluated function bytecode value.
    let compiled = unsafe { Value::from_raw(ctx.clone(), raw) };
    let mut len = 0;
    // SAFETY: The compiled value remains live until the writer finishes.
    let buffer = unsafe {
        qjs::JS_WriteObject(
            ctx.as_raw().as_ptr(),
            &mut len,
            compiled.as_raw(),
            qjs::JS_WRITE_OBJ_BYTECODE as _,
        )
    };
    if buffer.is_null() {
        panic!("serialize fixed JS bootstrap: {:?}", ctx.catch());
    }
    // SAFETY: Copy the writer's buffer before freeing with QuickJS's allocator.
    unsafe {
        let bytes = std::slice::from_raw_parts(buffer, len as usize).to_vec();
        qjs::js_free(ctx.as_raw().as_ptr(), buffer.cast());
        bytes
    }
}

// Smoke-check the generated global scripts in a separate build-time Context.
fn eval_global(ctx: &Ctx<'_>, bytes: &[u8]) {
    // SAFETY: These bytes were generated by compile_global in this build.
    let value = unsafe {
        qjs::JS_ReadObject(ctx.as_raw().as_ptr(), bytes.as_ptr(), bytes.len() as _,
            qjs::JS_READ_OBJ_BYTECODE as _)
    };
    if unsafe { qjs::JS_IsException(value) } {
        panic!("read fixed JS bytecode: {:?}", ctx.catch());
    }
    // SAFETY: EvalFunction consumes the owned bytecode value on all paths.
    let result = unsafe { qjs::JS_EvalFunction(ctx.as_raw().as_ptr(), value) };
    if unsafe { qjs::JS_IsException(result) } {
        panic!("evaluate fixed JS bytecode: {:?}", ctx.catch());
    }
    drop(unsafe { Value::from_raw(ctx.clone(), result) });
}

fn main() {
    for source in [
        "src/linkedom/worker.min.js",
        "src/bootstrap_common.js",
        "src/browser_url.rs",
        "src/linkedom_adapter.js",
    ] {
        println!("cargo:rerun-if-changed={source}");
    }

    let runtime = Runtime::new().expect("create build-time QuickJS runtime");
    let context = Context::full(&runtime).expect("create build-time QuickJS context");
    let output = PathBuf::from(env::var_os("OUT_DIR").expect("Cargo OUT_DIR"));
    let module_bytes = context.with(|ctx| {
        let module = Module::declare(
            ctx.clone(),
            "linkedom-worker",
            fs::read("src/linkedom/worker.min.js").expect("read bundled LinkeDOM source"),
        ).expect("compile LinkeDOM module");
        let module_bytes = module.write(WriteOptions::default())
            .expect("serialize LinkeDOM module");
        fs::write(output.join("linkedom-worker.qbc"), &module_bytes)
            .expect("write LinkeDOM bytecode");

        for (source, name) in [
            ("src/bootstrap_common.js", "browser-bootstrap.qbc"),
            ("src/linkedom_adapter.js", "linkedom-adapter.qbc"),
        ] {
            let bytes = fs::read(source).expect("read bundled bootstrap source");
            fs::write(output.join(name), compile_global(&ctx, &bytes))
                .expect("write fixed JS bytecode");
        }
        module_bytes
    });

    // Validate the compiled scripts together in a fresh Context, preserving
    // the production bootstrap -> module -> adapter -> HTML initialization order.
    let other = Context::full(&runtime).expect("create independent validation context");
    other.with(|ctx| {
        let globals = ctx.globals();
        globals.set("document", Object::new(ctx.clone()).unwrap()).unwrap();
        globals.set("__r_initial_href", "https://rakers.test/").unwrap();
        globals.set("__r_initial_ua", "rakers-build-test").unwrap();
        browser_url::install(&ctx).expect("install build-time URL bridge");
        eval_global(&ctx, &fs::read(output.join("browser-bootstrap.qbc")).unwrap());
        globals.remove("__r_initial_href").unwrap();
        globals.remove("__r_initial_ua").unwrap();
        let href: String = ctx.eval("location.href").unwrap();
        let user_agent: String = ctx.eval("navigator.userAgent").unwrap();
        assert_eq!(href, "https://rakers.test/");
        assert_eq!(user_agent, "rakers-build-test");
        let query_url: String = ctx.eval("new URL('?api=1', 'https://rakers.test/page?old=1#before').href").unwrap();
        assert_eq!(query_url, "https://rakers.test/page?api=1");

        let module = unsafe { Module::load(ctx.clone(), &module_bytes) }
            .expect("load precompiled LinkeDOM module");
        let (module, ready) = module.eval().expect("evaluate precompiled LinkeDOM module");
        ready.finish::<()>().expect("finish precompiled LinkeDOM module");
        globals.set("_r_linkedom", module.namespace().unwrap()).unwrap();
        eval_global(&ctx, &fs::read(output.join("linkedom-adapter.qbc")).unwrap());
        let init: Function<'_> = globals.get("_r_initialize_linkedom").unwrap();
        init.call::<_, ()>(("<html><body><main>bytecode-ok</main></body></html>",))
            .expect("initialize precompiled LinkeDOM");
        let text: String = ctx.eval("document.querySelector('main').textContent").unwrap();
        assert_eq!(text, "bytecode-ok");
    });
}
